import { describe, expect, it } from "vitest";
import {
  mcpProtectedResourceMetadata,
  mcpProtectedResourceMetadataUrl,
  mcpWwwAuthenticate,
} from "./mcp-oauth.js";

describe("MCP OAuth metadata", () => {
  it("points MCP clients from the resource to the authorization server", () => {
    expect(mcpProtectedResourceMetadata("https://superlog.sh")).toEqual({
      authorization_servers: ["https://superlog.sh/api/auth"],
      bearer_methods_supported: ["header"],
      resource: "https://superlog.sh/api/mcp",
      resource_documentation: "https://docs.superlog.sh/api-reference/mcp",
      resource_name: "Superlog",
      scopes_supported: ["mcp", "offline_access"],
    });
  });

  it("names the resource metadata in the 401 challenge", () => {
    expect(mcpProtectedResourceMetadataUrl("https://superlog.sh")).toBe(
      "https://superlog.sh/.well-known/oauth-protected-resource/api/mcp",
    );
    expect(mcpWwwAuthenticate("https://superlog.sh")).toBe(
      'Bearer realm="superlog", resource_metadata="https://superlog.sh/.well-known/oauth-protected-resource/api/mcp", scope="mcp offline_access"',
    );
  });
});

import { beforeEach, describe, expect, it, vi } from "vitest";

const mocks = vi.hoisted(() => ({
  auth: vi.fn(),
  fetch: vi.fn(),
  lookup: vi.fn(),
}));

vi.mock("node:dns/promises", () => ({ lookup: mocks.lookup }));
vi.mock("undici", () => ({
  Agent: class MockAgent {
    close = vi.fn(async () => undefined);
    destroy = vi.fn(async () => undefined);
  },
  fetch: mocks.fetch,
}));
vi.mock("@modelcontextprotocol/sdk/client/auth.js", async (importOriginal) => ({
  ...(await importOriginal()),
  auth: mocks.auth,
}));

import { beginCustomMcpOAuth } from "./custom-mcp.js";

describe("custom MCP OAuth discovery", () => {
  beforeEach(() => {
    mocks.auth.mockReset();
    mocks.fetch.mockReset();
    mocks.lookup.mockReset();
    mocks.lookup.mockResolvedValue([
      { address: "93.184.216.34", family: 4 },
    ]);
  });

  it("honors protected resource metadata advertised by the MCP challenge", async () => {
    mocks.fetch.mockResolvedValue(
      new Response(null, {
        headers: {
          "www-authenticate":
            'Bearer resource_metadata="https://mcp.example.test/.well-known/oauth-protected-resource", scope="openid offline_access"',
        },
        status: 401,
      }),
    );
    mocks.auth.mockImplementation(async (provider) => {
      provider.redirectToAuthorization(
        new URL("https://authorization.example.test/oauth2/authorize"),
      );
      return "REDIRECT";
    });

    await beginCustomMcpOAuth({
      connectionState: "oauth-state",
      mcpUrl: "https://mcp.example.test/mcp",
      redirectUrl: "https://responder.example/api/integrations/axiom/callback",
    });

    expect(mocks.fetch).toHaveBeenCalledWith(
      "https://mcp.example.test/mcp",
      expect.objectContaining({ method: "GET" }),
    );
    expect(mocks.auth).toHaveBeenCalledWith(
      expect.anything(),
      expect.objectContaining({
        resourceMetadataUrl: new URL(
          "https://mcp.example.test/.well-known/oauth-protected-resource",
        ),
        scope: "openid offline_access",
      }),
    );
  });
});

import { afterEach, expect, it, vi } from "vitest";
import { PgDialect } from "drizzle-orm/pg-core";
import {
  acquireSubscriptionCredential,
  chooseOrganizationModelCredential,
  selectOrganizationModelCredential,
  persistSubscriptionCredential,
  releaseSubscriptionCredential,
  SubscriptionCredentialUnavailableError,
} from "./automation-model-credentials.js";
import { getDatabase } from "./client.js";
import {
  decryptCredentials,
  encryptCredentials,
} from "../credentials/encryption.js";
vi.mock("./client.js", () => ({ getDatabase: vi.fn() }));
afterEach(() => {
  vi.clearAllMocks();
  vi.unstubAllEnvs();
});
const authJson = JSON.stringify({
  tokens: {
    id_token: "id",
    access_token: "access",
    refresh_token: "refresh",
    account_id: "account",
  },
});
const owner = {
  credentialId: "credential",
  organizationId: "organization",
  leaseId: "lease",
};
it("acquires an exclusive scoped lease before exposing the native credential", async () => {
  vi.stubEnv(
    "CREDENTIAL_ENCRYPTION_KEY",
    Buffer.alloc(32, 1).toString("base64"),
  );
  const returning = vi
    .fn()
    .mockResolvedValue([
      { encryptedCredentials: encryptCredentials({ authJson }) },
    ]);
  const where = vi.fn().mockReturnValue({ returning });
  const set = vi.fn().mockReturnValue({ where });
  vi.mocked(getDatabase).mockReturnValue({ update: () => ({ set }), transaction: async (callback: (tx: unknown) => Promise<unknown>) => callback({ update: () => ({ set }) }) } as never);
  await expect(
    acquireSubscriptionCredential({
      ...owner,
      expiresAt: new Date(Date.now() + 60000),
    }),
  ).resolves.toBe(authJson);
  expect(set).toHaveBeenCalledWith({
    subscriptionLeaseId: owner.leaseId,
    subscriptionLeaseExpiresAt: expect.any(Date),
  });
  expect(new PgDialect().sqlToQuery(where.mock.calls[0][0]).sql).not.toContain(
    " or ",
  );
  expect(new PgDialect().sqlToQuery(where.mock.calls[0][0]).params).toEqual(
    expect.arrayContaining([
      "credential",
      "organization",
      "chatgpt_subscription",
      "active",
    ]),
  );
  returning.mockResolvedValue([]);
  await expect(
    acquireSubscriptionCredential({
      ...owner,
      expiresAt: new Date(Date.now() + 60000),
    }),
  ).rejects.toBeInstanceOf(SubscriptionCredentialUnavailableError);
});
it("persists only under the owning lease and rejects account switches", async () => {
  vi.stubEnv(
    "CREDENTIAL_ENCRYPTION_KEY",
    Buffer.alloc(32, 1).toString("base64"),
  );
  const where = vi
    .fn()
    .mockReturnValue({
      returning: vi.fn().mockResolvedValue([{ id: "credential" }]),
    });
  const set = vi.fn().mockReturnValue({ where });
  vi.mocked(getDatabase).mockReturnValue({ update: () => ({ set }) } as never);
  await persistSubscriptionCredential({
    ...owner,
    authJson,
    previousAccountId: "account",
  });
  expect(decryptCredentials(set.mock.calls[0][0].encryptedCredentials)).toEqual(
    { authJson },
  );
  expect(new PgDialect().sqlToQuery(where.mock.calls[0][0]).params).toEqual([
    "credential",
    "organization",
    "chatgpt_subscription",
    "lease",
  ]);
  await expect(
    persistSubscriptionCredential({
      ...owner,
      authJson,
      previousAccountId: "another",
    }),
  ).rejects.toThrow("account changed");
  await releaseSubscriptionCredential(owner);
  expect(set).toHaveBeenLastCalledWith({
    subscriptionLeaseId: null,
    subscriptionLeaseExpiresAt: null,
  });
});

it("rolls back the lease claim when the stored credential is invalid", async () => {
  vi.stubEnv("CREDENTIAL_ENCRYPTION_KEY", Buffer.alloc(32, 1).toString("base64"));
  let committed = false;
  const transaction = vi.fn(async (callback: (db: unknown) => Promise<unknown>) => { const result = await callback(tx); committed = true; return result; });
  const tx = { update: () => ({ set: () => ({ where: () => ({ returning: async () => [{ encryptedCredentials: encryptCredentials({ authJson: "invalid" }) }] }) }) }) };
  vi.mocked(getDatabase).mockReturnValue({ ...tx, transaction } as never);
  await expect(acquireSubscriptionCredential({ ...owner, expiresAt: new Date() })).rejects.toThrow();
  expect(transaction).toHaveBeenCalledOnce();
  expect(committed).toBe(false);
});

it("prefers a ChatGPT subscription for Codex and otherwise the newest API key", () => {
  const older = { id: "older-key", authType: "api_key" as const, createdAt: new Date("2026-09-01") };
  const newer = { id: "newer-key", authType: "api_key" as const, createdAt: new Date("2026-09-20") };
  const subscription = { id: "subscription", authType: "chatgpt_subscription" as const, createdAt: new Date("2026-08-01") };
  expect(chooseOrganizationModelCredential([older, subscription, newer], "codex")).toBe("subscription");
  expect(chooseOrganizationModelCredential([older, subscription, newer], "opencode")).toBe("newer-key");
  expect(chooseOrganizationModelCredential([subscription], "opencode")).toBeNull();
  expect(chooseOrganizationModelCredential([], "codex")).toBeNull();
});

it("selects among the organization's active credentials for the provider", async () => {
  const where = vi.fn().mockResolvedValue([
    { id: "key", authType: "api_key", createdAt: new Date() },
  ]);
  vi.mocked(getDatabase).mockReturnValue({ select: () => ({ from: () => ({ where }) }) } as never);
  await expect(selectOrganizationModelCredential({ harness: "claude_agent_sdk", organizationId: "organization", provider: "anthropic" })).resolves.toBe("key");
  expect(new PgDialect().sqlToQuery(where.mock.calls[0][0]).params).toEqual(["organization", "anthropic", "active"]);
});

import { describe, expect, it } from "vitest";
import { socialAuthErrorMessage, socialAuthUrls } from "./social-auth-url.js";

describe("social auth return URLs", () => {
  it("removes stale callback state while preserving application parameters", () => {
    const urls = socialAuthUrls(
      "https://responder.example/app?twclid=tracking&error=email_not_found&error=email_not_found&error_description=missing&signed_up=1&signup_intent=stale",
      "signup-attempt",
    );

    expect(urls.callbackURL).toBe(
      "https://responder.example/app?twclid=tracking",
    );
    expect(urls.errorCallbackURL).toBe(
      "https://responder.example/app?twclid=tracking",
    );
    expect(urls.newUserCallbackURL).toBe(
      "https://responder.example/app?twclid=tracking&signed_up=1&signup_intent=signup-attempt",
    );
  });
});

describe("social auth error messages", () => {
  it("explains a missing GitHub email", () => {
    expect(socialAuthErrorMessage("?error=email_not_found")).toContain(
      "an email address",
    );
  });

  it("uses a safe message for other provider errors", () => {
    expect(socialAuthErrorMessage("?error=invalid_code")).toBe(
      "Social sign in failed. Please try again.",
    );
    expect(socialAuthErrorMessage("")).toBeNull();
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";
import {
  aiGatewayModelId,
  listAIGatewayModels,
  automationModelCostMicros,
  getAIGatewayModelPricing,
  resetAIGatewayPricingCache,
} from "./model-pricing.js";

describe("AI Gateway model pricing", () => {
  afterEach(() => resetAIGatewayPricingCache());

  it("maps automation models to gateway slugs", () => {
    expect(aiGatewayModelId("openai", "gpt-5.4")).toBe("openai/gpt-5.4");
    expect(aiGatewayModelId("anthropic", "claude-sonnet-4-5")).toBe(
      "anthropic/claude-sonnet-4.5",
    );
    expect(aiGatewayModelId("anthropic", "claude-haiku-4-5-20251001")).toBe(
      "anthropic/claude-haiku-4.5",
    );
    expect(aiGatewayModelId("anthropic", "claude-3-5-sonnet-20241022")).toBe(
      "anthropic/claude-3.5-sonnet",
    );
    expect(aiGatewayModelId("anthropic", "claude-3-haiku-20240307")).toBe(
      "anthropic/claude-3-haiku",
    );
    expect(aiGatewayModelId("anthropic", "claude-opus-5")).toBe(
      "anthropic/claude-opus-5",
    );
    expect(aiGatewayModelId("anthropic", "anthropic/claude-sonnet-5")).toBe(
      "anthropic/claude-sonnet-5",
    );
    expect(aiGatewayModelId("xai", "grok-4.1-fast-reasoning")).toBe(
      "spacexai/grok-4.1-fast-reasoning",
    );
    expect(aiGatewayModelId("google", "gemini-3-pro")).toBe("google/gemini-3-pro");
  });

  it("prices each token class and applies long-context tiers", () => {
    const pricing = {
      input: "0.000003",
      input_cache_read: "0.0000003",
      input_cache_write: "0.00000375",
      input_tiers: [
        { cost: "0.000003", max: 200_001, min: 0 },
        { cost: "0.000006", min: 200_001 },
      ],
      output: "0.000015",
    };

    expect(automationModelCostMicros(pricing, {
      cacheWriteTokens: 1_000,
      cachedInputTokens: 10_000,
      inputTokens: 1_000,
      outputTokens: 1_000,
    })).toBe(3_000 + 3_000 + 3_750 + 15_000);
    expect(automationModelCostMicros(pricing, {
      cacheWriteTokens: 0,
      cachedInputTokens: 0,
      inputTokens: 250_000,
      outputTokens: 0,
    })).toBe(1_500_000);
  });

  it("falls back to the input price when a cache price is missing", () => {
    expect(automationModelCostMicros(
      { input: "0.000001", output: "0.000002" },
      { cacheWriteTokens: 10, cachedInputTokens: 10, inputTokens: 10, outputTokens: 10 },
    )).toBe(50);
    expect(automationModelCostMicros(
      { output: "0.000002" },
      { cacheWriteTokens: 0, cachedInputTokens: 0, inputTokens: 1, outputTokens: 1 },
    )).toBeNull();
  });

  it("caches the public model catalog", async () => {
    const fetchPricing = vi.fn().mockResolvedValue(Response.json({
      data: [{ id: "openai/gpt-5.4", pricing: { input: "1", output: "2" } }],
    }));

    await expect(getAIGatewayModelPricing("openai/gpt-5.4", {
      fetch: fetchPricing,
      now: () => 0,
    })).resolves.toEqual({ input: "1", output: "2" });
    await expect(getAIGatewayModelPricing("openai/unknown", {
      fetch: fetchPricing,
      now: () => 1_000,
    })).resolves.toBeNull();
    expect(fetchPricing).toHaveBeenCalledOnce();
  });

  it("lists a provider's priced gateway language models without the creator prefix", async () => {
    const fetchCatalog = vi.fn().mockResolvedValue(Response.json({
      data: [
        { id: "spacexai/grok-5", name: "Grok 5", pricing: { input: "0.000001", output: "0.000002" }, type: "language" },
        { id: "spacexai/grok-unpriced", name: "Grok Unpriced", type: "language" },
        { id: "spacexai/grok-imagine", name: "Grok Imagine", pricing: { image: "0.04" }, type: "image" },
        { id: "openai/gpt-5.4", name: "GPT-5.4", pricing: { input: "0.000001", output: "0.000002" }, type: "language" },
      ],
    }));

    await expect(listAIGatewayModels("xai", { fetch: fetchCatalog })).resolves.toEqual([
      { id: "grok-5", name: "Grok 5" },
    ]);
  });

  it("orders a provider's gateway models from newest to oldest", async () => {
    const priced = { input: "0.000001", output: "0.000002" };
    const fetchCatalog = vi.fn().mockResolvedValue(Response.json({
      data: [
        { id: "anthropic/claude-undated", name: "Claude Undated", pricing: priced, type: "language" },
        { id: "anthropic/claude-old", name: "Claude Old", pricing: priced, released: 1_700_000_000, type: "language" },
        { id: "anthropic/claude-new", name: "Claude New", pricing: priced, released: 1_800_000_000, type: "language" },
      ],
    }));

    await expect(listAIGatewayModels("anthropic", { fetch: fetchCatalog })).resolves.toEqual([
      { id: "claude-new", name: "Claude New" },
      { id: "claude-old", name: "Claude Old" },
      { id: "claude-undated", name: "Claude Undated" },
    ]);
  });
});

import { describe, expect, it, vi } from "vitest";
import { createBillingEnabledLoader } from "./billing-api";

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status });
}

describe("billing enabled loader", () => {
  it("shares one request across callers", async () => {
    const fetcher = vi.fn().mockResolvedValue(json({ enabled: true }));
    const billingEnabled = createBillingEnabledLoader(fetcher);

    await expect(Promise.all([billingEnabled(), billingEnabled()])).resolves.toEqual([true, true]);
    await expect(billingEnabled()).resolves.toBe(true);
    expect(fetcher).toHaveBeenCalledTimes(1);
  });

  it("asks again after a failed request", async () => {
    const fetcher = vi.fn()
      .mockResolvedValueOnce(json({ error: "Too many requests" }, 429))
      .mockResolvedValueOnce(json({ enabled: true }));
    const billingEnabled = createBillingEnabledLoader(fetcher);

    await expect(billingEnabled()).resolves.toBe(false);
    await expect(billingEnabled()).resolves.toBe(true);
    expect(fetcher).toHaveBeenCalledTimes(2);
  });
});

import { beforeEach, describe, expect, it, vi } from "vitest";

const sentryMocks = vi.hoisted(() => ({
  browserTracingIntegration: vi.fn().mockReturnValue("browser-tracing"),
  init: vi.fn(),
  isInitialized: vi.fn().mockReturnValue(false),
  setTag: vi.fn(),
  setUser: vi.fn(),
}));

vi.mock("@sentry/react", () => sentryMocks);

import {
  initializeBrowserMonitoring,
  setBrowserMonitoringIdentity,
  startSignedInBrowserTelemetry,
} from "./browser-monitoring";

describe("browser error monitoring", () => {
  beforeEach(() => {
    sentryMocks.browserTracingIntegration.mockClear();
    sentryMocks.init.mockClear();
    sentryMocks.isInitialized.mockReset().mockReturnValue(false);
    sentryMocks.setTag.mockClear();
    sentryMocks.setUser.mockClear();
  });

  it("does not initialize without a DSN", () => {
    expect(initializeBrowserMonitoring({})).toBe(false);
    expect(sentryMocks.init).not.toHaveBeenCalled();
  });

  it("initializes without tracing by default", () => {
    expect(
      initializeBrowserMonitoring({
        dsn: "https://public@example.invalid/1",
        environment: "production",
        release: "abc123",
      }),
    ).toBe(true);

    expect(sentryMocks.init).toHaveBeenCalledWith({
      dsn: "https://public@example.invalid/1",
      environment: "production",
      integrations: [],
      release: "abc123",
      sendDefaultPii: false,
      tracesSampleRate: 0,
    });
  });

  it("sets names and clears the old name while a new organization loads", () => {
    setBrowserMonitoringIdentity("user-1", "organization-1", "Ada", "Acme");
    expect(sentryMocks.setUser).toHaveBeenLastCalledWith({ id: "user-1", username: "Ada" });
    expect(sentryMocks.setTag).toHaveBeenLastCalledWith("organization_name", "Acme");
    setBrowserMonitoringIdentity("user-1", "organization-2", "Ada");
    expect(sentryMocks.setTag).toHaveBeenLastCalledWith("organization_name", "");
  });

  it("clears identity fields after sign out", () => {
    setBrowserMonitoringIdentity("user-1", "organization-1", "Ada", "Acme");
    setBrowserMonitoringIdentity();

    expect(sentryMocks.setUser).toHaveBeenLastCalledWith(null);
    expect(sentryMocks.setTag).toHaveBeenCalledWith("organization_id", "");
    expect(sentryMocks.setTag).toHaveBeenLastCalledWith("organization_name", "");
  });

  it("starts browser traces after sign-in only when a sample rate is set", async () => {
    vi.stubGlobal("window", { location: { origin: "https://superlog.sh" } });
    const startBrowserTelemetry = vi.fn().mockReturnValue(true);
    const load = vi.fn().mockResolvedValue({ startBrowserTelemetry });

    await expect(startSignedInBrowserTelemetry({}, load)).resolves.toBe(false);
    await expect(startSignedInBrowserTelemetry({ otelTracesSampleRate: "0" }, load)).resolves.toBe(false);
    expect(load).not.toHaveBeenCalled();

    await expect(
      startSignedInBrowserTelemetry(
        { environment: " production ", otelTracesSampleRate: "0.5", release: "web-1" },
        load,
      ),
    ).resolves.toBe(true);
    expect(startBrowserTelemetry).toHaveBeenCalledWith({
      environment: "production",
      origin: "https://superlog.sh",
      release: "web-1",
      sampleRate: 0.5,
    });

    await expect(
      startSignedInBrowserTelemetry(
        { otelTracesSampleRate: "1" },
        vi.fn().mockRejectedValue(new Error("chunk failed")),
      ),
    ).resolves.toBe(false);
    vi.unstubAllGlobals();
  });
});

import { describe, expect, it, vi } from "vitest";
import {
  grafanaSelfHostedArgs,
  grafanaSelfHostedProcess,
  isGrafanaReadOnlyTool,
} from "./grafana-mcp.js";

vi.mock("./egress-proxy.js", () => ({
  startEgressProxy: vi.fn(async () => ({
    close: async () => undefined,
    server: { unref: vi.fn() },
    url: "socks5h://127.0.0.1:41000",
  })),
}));

describe("Grafana MCP", () => {
  it("disables write, raw API, and SQL tools in the self-hosted process", () => {
    const args = grafanaSelfHostedArgs();
    const enabledTools = args
      .find((arg) => arg.startsWith("--enabled-tools="))!
      .slice("--enabled-tools=".length)
      .split(",");

    expect(args).toContain("--disable-write");
    expect(args).toContain("--usage-stats=disabled");
    expect(enabledTools).toEqual(
      expect.arrayContaining(["prometheus", "loki", "dashboard", "alerting"]),
    );
    for (const category of [
      "api",
      "sql",
      "admin",
      "provisioning",
      "rendering",
      "snapshot",
      "plugin",
      "assistant",
    ]) {
      expect(enabledTools).not.toContain(category);
    }
  });

  it("starts mcp-grafana with only the connection's credential and the egress proxy", async () => {
    await expect(grafanaSelfHostedProcess(
      { grafanaUrl: "https://grafana.example.com", serviceAccountToken: "glsa_token" },
      { MCP_GRAFANA_BINARY: "/usr/local/bin/mcp-grafana" },
    )).resolves.toEqual({
      args: grafanaSelfHostedArgs(),
      command: "/usr/local/bin/mcp-grafana",
      env: {
        DO_NOT_TRACK: "1",
        GRAFANA_SERVICE_ACCOUNT_TOKEN: "glsa_token",
        GRAFANA_SOCKS5_PROXY: "socks5h://127.0.0.1:41000",
        GRAFANA_URL: "https://grafana.example.com",
      },
    });
  });

  it("allows only tools annotated read-only", () => {
    expect(isGrafanaReadOnlyTool({ annotations: { readOnlyHint: true }, name: "query_prometheus" })).toBe(true);
    expect(isGrafanaReadOnlyTool({ name: "update_dashboard" })).toBe(false);
    expect(isGrafanaReadOnlyTool({ annotations: { readOnlyHint: false }, name: "create_incident" })).toBe(false);
    expect(isGrafanaReadOnlyTool(null)).toBe(false);
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";
import type {
  AutomationModelUsageRecord,
  completeResponderModelUsage,
  listUnbilledAutomationModelUsage,
  markAutomationModelUsageBilled,
  markAutomationModelUsageBillingAttempted,
  purgeAbandonedResponderModelUsage,
  recordAutomationModelUsage,
  reserveResponderModelUsage,
  setAutomationModelUsageCost,
} from "../db/automation-model-usage.js";
import type {
  checkUsageAllowance,
  trackAutomationInferenceUsage,
} from "../billing/autumn.js";
import type { getAIGatewayModelPricing } from "./model-pricing.js";
import {
  completeResponderInference,
  recordBrokeredModelUsage,
  reserveResponderInference,
  settleUnbilledAutomationModelUsage,
} from "./model-usage-billing.js";

// Model usage at provider cost, whichever edition's prices are composed in.
vi.mock("../billing/usage-pricing.js", () => ({
  inferenceChargeMicros: (costMicros: number) => costMicros,
  sandboxChargeMicros: () => 0,
}));

const usage = {
  cacheWriteTokens: 0,
  cachedInputTokens: 0,
  inputTokens: 1_000,
  outputTokens: 100,
};

function usageRecord(
  id: string,
  costMicros: number | null,
  inferenceSource: AutomationModelUsageRecord["inferenceSource"] = "responder",
): AutomationModelUsageRecord {
  return {
    ...usage,
    costMicros,
    id,
    inferenceSource,
    model: "gpt-5.4",
    organizationId: "organization-1",
    provider: "openai",
    runId: "run-1",
  };
}

function dependencies() {
  return {
    complete: vi.fn<typeof completeResponderModelUsage>(
      async (id, _usage, costMicros) => usageRecord(id, costMicros),
