// Installs the pinned grafana/mcp-grafana release used by the worker for
// self-hosted Grafana context. Production images install the same version in
// apps/worker/Dockerfile; keep the version and checksums in sync.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
  chmodSync,
  copyFileSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  renameSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

const MCP_GRAFANA_VERSION = "1.5.1";

const releaseAssets = {
  "darwin-arm64": {
    name: "mcp-grafana_Darwin_arm64.tar.gz",
    sha256: "d0f7e159680a8698f9475c7ec8a06cb65d9a10462f80165d1927e7d5a4975e21",
  },
  "darwin-x64": {
    name: "mcp-grafana_Darwin_x86_64.tar.gz",
    sha256: "7cbcf7302c55fff87da53488492d967badeb1587f0ff576bf3da417f9eab8c18",
  },
  "linux-arm64": {
    name: "mcp-grafana_Linux_arm64.tar.gz",
    sha256: "6ae7bd9d89879f9332b76ba95865bed1aa59e89ce2a30f9bbb91d67e8dfb6b57",
  },
  "linux-x64": {
    name: "mcp-grafana_Linux_x86_64.tar.gz",
    sha256: "3ef1c7a66aab3ba149de53681d72ea58244baa41331eb3aed9cdd2f68acc0db7",
  },
};

const binaryPath = join(
  dirname(fileURLToPath(import.meta.url)),
  "..",
  ".tools",
  `mcp-grafana-${MCP_GRAFANA_VERSION}`,
  "mcp-grafana",
);

async function install() {
  if (existsSync(binaryPath)) {
    process.stdout.write(`${binaryPath}\n`);
    return;
  }

  const asset = releaseAssets[`${process.platform}-${process.arch}`];
  if (!asset) {
    throw new Error(
      `mcp-grafana ${MCP_GRAFANA_VERSION} has no pinned build for ${process.platform}-${process.arch}`,
    );
  }
  const response = await fetch(
    `https://github.com/grafana/mcp-grafana/releases/download/v${MCP_GRAFANA_VERSION}/${asset.name}`,
    { signal: AbortSignal.timeout(120_000) },
  );
  if (!response.ok) {
    throw new Error(`Unable to download mcp-grafana (${response.status})`);
  }
  const archive = Buffer.from(await response.arrayBuffer());
  const digest = createHash("sha256").update(archive).digest("hex");
  if (digest !== asset.sha256) {
    throw new Error(`mcp-grafana checksum mismatch for ${asset.name}`);
  }

  const workDirectory = mkdtempSync(join(tmpdir(), "mcp-grafana-"));
  try {
    const archivePath = join(workDirectory, asset.name);
    writeFileSync(archivePath, archive);
    execFileSync("tar", ["-xzf", archivePath, "-C", workDirectory, "mcp-grafana"]);
    mkdirSync(dirname(binaryPath), { recursive: true });
    // Copy next to the destination first so an interrupted install never
    // leaves a partial binary at the final path.
    const stagedPath = `${binaryPath}.${process.pid}`;
    copyFileSync(join(workDirectory, "mcp-grafana"), stagedPath);
    chmodSync(stagedPath, 0o755);
    renameSync(stagedPath, binaryPath);
  } finally {
    rmSync(workDirectory, { force: true, recursive: true });
  }
  process.stdout.write(`${binaryPath}\n`);
}

await install();

// OAuth for the management MCP server. MCP clients register themselves,
// send the person through Superlog sign-in and a workspace choice, and then
// call /api/mcp with an access token bound to that person and workspace.

export const mcpOAuthScope = "mcp";
export const mcpOAuthScopes = [mcpOAuthScope, "offline_access"];

// Prefixes tell OAuth tokens apart from API keys (`slk_`) and help secret
// scanners recognize them. They are not stored.
export const mcpAccessTokenPrefix = "slo_";
export const mcpRefreshTokenPrefix = "slr_";

// The sign-in, workspace choice, and consent steps share one page.
export const mcpOAuthPagePath = "/oauth/authorize";

export const mcpResourcePath = "/api/mcp";
export const authBasePath = "/api/auth";

export function mcpResourceUrl(baseUrl: string): string {
  return new URL(mcpResourcePath, baseUrl).toString();
}

export function mcpAuthorizationServerUrl(baseUrl: string): string {
  return new URL(authBasePath, baseUrl).toString();
}

export function mcpProtectedResourceMetadataUrl(baseUrl: string): string {
  return new URL(
    `/.well-known/oauth-protected-resource${mcpResourcePath}`,
    baseUrl,
  ).toString();
}

// RFC 9728 metadata. MCP clients read it to find the authorization server.
export function mcpProtectedResourceMetadata(baseUrl: string) {
  return {
    authorization_servers: [mcpAuthorizationServerUrl(baseUrl)],
    bearer_methods_supported: ["header"],
    resource: mcpResourceUrl(baseUrl),
    resource_documentation: "https://docs.superlog.sh/api-reference/mcp",
    resource_name: "Superlog",
    scopes_supported: mcpOAuthScopes,
  };
}

export function mcpWwwAuthenticate(baseUrl: string): string {
  return `Bearer realm="superlog", resource_metadata="${mcpProtectedResourceMetadataUrl(baseUrl)}", scope="${mcpOAuthScopes.join(" ")}"`;
}

import { z } from "zod";
import {
  createWorkspaceSecretRecord,
  findWorkspaceSecretByName,
  type WorkspaceSecretSummary,
} from "../../../../packages/core/src/db/workspace-secrets.js";
import { workspaceSecretEnvironmentVariableNameReservation } from "../../../../packages/core/src/workspace-secret-names.js";
import {
  createDaytonaWorkspaceSecret,
  deleteDaytonaWorkspaceSecret,
} from "./daytona-secrets.js";

const secretHostSchema = z
  .string()
  .trim()
  .toLowerCase()
  .min(1)
  .max(253)
  .regex(
    /^(?:\*\.)?[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)*$/,
    "Use a hostname without a scheme, path, or port",
  );

export const workspaceSecretInputSchema = z.object({
  name: z
    .string()
    .trim()
    .toUpperCase()
    .min(1, "Environment variable name is required")
    .max(80)
    .regex(
      /^[A-Z_][A-Z0-9_]*$/,
      "Use an uppercase environment variable name",
    )
    .superRefine((name, context) => {
      const reservation = workspaceSecretEnvironmentVariableNameReservation(name);
      if (reservation) {
        context.addIssue({ code: "custom", message: reservation });
      }
    }),
  value: z.string().min(1, "Secret value is required").max(65_536),
  allowedHosts: z
    .array(secretHostSchema)
    .min(1, "Add at least one allowed host")
    .max(20)
    .transform((hosts) => [...new Set(hosts)]),
});

export type WorkspaceSecretInput = z.output<typeof workspaceSecretInputSchema>;

function isWorkspaceSecretNameConflict(error: unknown): boolean {
  return (
    typeof error === "object" &&
    error !== null &&
    "code" in error &&
    error.code === "23505" &&
    "constraint" in error &&
    error.constraint === "workspace_secrets_organization_name_idx"
  );
}

// Stores the value in Daytona and records only its metadata. The Daytona
// secret is removed again if the record cannot be saved.
export async function storeWorkspaceSecret(input: {
  organizationId: string;
  secret: WorkspaceSecretInput;
  userId: string;
}): Promise<
  | { ok: true; secret: WorkspaceSecretSummary }
  | { ok: false; error: string; status: 409 | 502 }
> {
  const { name, allowedHosts, value } = input.secret;
  const conflict = {
    error: `${name} already exists in this workspace`,
    ok: false,
    status: 409,
  } as const;
  const existing = await findWorkspaceSecretByName({
    organizationId: input.organizationId,
    name,
  });
  if (existing) return conflict;

  let daytonaSecret: { id: string; name: string } | null = null;
  try {
    daytonaSecret = await createDaytonaWorkspaceSecret({ value, allowedHosts });
    const secret = await createWorkspaceSecretRecord({
      organizationId: input.organizationId,
      userId: input.userId,
      name,
      allowedHosts,
      daytonaSecretId: daytonaSecret.id,
      daytonaSecretName: daytonaSecret.name,
    });
    return { ok: true, secret };
  } catch (error) {
    if (daytonaSecret) {
      try {
        await deleteDaytonaWorkspaceSecret(daytonaSecret.id);
      } catch (cleanupError) {
        console.error("Unable to clean up workspace secret", {
          cleanupError,
          daytonaSecretId: daytonaSecret.id,
        });
        return {
          error: "Unable to clean up workspace secret after storage failed",
          ok: false,
          status: 502,
        };
      }
    }
    if (isWorkspaceSecretNameConflict(error)) return conflict;
    return { error: "Unable to store workspace secret", ok: false, status: 502 };
  }
}

import { randomUUID } from "node:crypto";
import { Daytona } from "@daytona/sdk";
import {
  daytonaClientOptions,
  isDaytonaNotFound,
  requireDaytonaClientConfig,
  type DaytonaClientConfig,
} from "@responder/core/daytona-config";

function daytonaClient(config: DaytonaClientConfig): Daytona {
  return new Daytona(daytonaClientOptions(config));
}

export async function createDaytonaWorkspaceSecret(input: {
  value: string;
  allowedHosts: string[];
}): Promise<{ id: string; name: string }> {
  const client = daytonaClient(requireDaytonaClientConfig());
  try {
    const secret = await client.secret.create({
      name: `responder_${randomUUID().replaceAll("-", "")}`,
      value: input.value,
      hosts: input.allowedHosts,
      description: "Responder workspace secret",
    });
    return { id: secret.id, name: secret.name };
  } finally {
    await client[Symbol.asyncDispose]().catch(() => undefined);
  }
}

export async function deleteDaytonaWorkspaceSecret(
  daytonaSecretId: string,
): Promise<void> {
  const client = daytonaClient(requireDaytonaClientConfig());
  try {
    let lastError: unknown;
    for (const delayMs of [0, 250, 1_000]) {
      if (delayMs > 0) {
        await new Promise((resolve) => setTimeout(resolve, delayMs));
      }
      try {
        await client.secret.delete(daytonaSecretId);
        return;
      } catch (error) {
        if (isDaytonaNotFound(error)) {
          return;
        }
        lastError = error;
      }
    }
    throw lastError;
  } finally {
    await client[Symbol.asyncDispose]().catch(() => undefined);
  }
}

import { parseSubscriptionAuth } from "../automations/chatgpt-subscription.js";
import { and, eq, isNull } from "drizzle-orm";
import type { AutomationModelProvider } from "../automations/config.js";
import {
  decryptCredentials,
  encryptCredentials,
} from "../credentials/encryption.js";
import { getDatabase } from "./client.js";
import { organizationModelCredentials } from "./schema.js";

interface StoredModelCredential extends Record<string, unknown> {
  apiKey: string;
}

function validateApiKey(apiKey: string): void {
  if (
    apiKey.length === 0 ||
    apiKey.length > 4_096 ||
    apiKey.trim() !== apiKey ||
    apiKey.includes("\0")
  ) {
    throw new Error("Model provider key is invalid");
  }
}

export async function createOrganizationModelCredential(input: {
  apiKey: string;
  label: string;
  organizationId: string;
  provider: AutomationModelProvider;
}) {
  validateApiKey(input.apiKey);
  const rows = await getDatabase()
    .insert(organizationModelCredentials)
    .values({
      credentialKeyVersion: 1,
      encryptedCredentials: encryptCredentials({ apiKey: input.apiKey }),
      label: input.label,
      lastFour: input.apiKey.slice(-4),
      organizationId: input.organizationId,
      provider: input.provider,
      status: "active",
    })
    .returning({ id: organizationModelCredentials.id });
  const credential = rows[0];
  if (!credential) throw new Error("Unable to create model credential");
  return { id: credential.id };
}

export async function rotateOrganizationModelCredential(input: {
  apiKey: string;
  credentialId: string;
  organizationId: string;
}): Promise<boolean> {
  validateApiKey(input.apiKey);
  const rows = await getDatabase()
    .update(organizationModelCredentials)
    .set({
      credentialKeyVersion: 1,
      encryptedCredentials: encryptCredentials({ apiKey: input.apiKey }),
      lastFour: input.apiKey.slice(-4),
      status: "active",
      updatedAt: new Date(),
    })
    .where(
      and(
        eq(organizationModelCredentials.id, input.credentialId),
        eq(organizationModelCredentials.organizationId, input.organizationId),
        eq(organizationModelCredentials.authType, "api_key"),
      ),
    )
    .returning({ id: organizationModelCredentials.id });
  return rows.length > 0;
}

export async function listOrganizationModelCredentials(organizationId: string) {
  return getDatabase()
    .select({
      id: organizationModelCredentials.id,
      label: organizationModelCredentials.label,
      authType: organizationModelCredentials.authType,
      lastFour: organizationModelCredentials.lastFour,
      lastValidatedAt: organizationModelCredentials.lastValidatedAt,
      provider: organizationModelCredentials.provider,
      status: organizationModelCredentials.status,
      createdAt: organizationModelCredentials.createdAt,
      updatedAt: organizationModelCredentials.updatedAt,
    })
    .from(organizationModelCredentials)
    .where(eq(organizationModelCredentials.organizationId, organizationId));
}

export async function getOrganizationModelCredential(input: {
  credentialId: string;
  organizationId: string;
  provider?: AutomationModelProvider;
}): Promise<{
  apiKey: string;
  provider: AutomationModelProvider;
  subscription?: { credentialId: string; authJson: string };
} | null> {
  const rows = await getDatabase()
    .select({
      authType: organizationModelCredentials.authType,
      credentialKeyVersion: organizationModelCredentials.credentialKeyVersion,
      encryptedCredentials: organizationModelCredentials.encryptedCredentials,
      provider: organizationModelCredentials.provider,
      status: organizationModelCredentials.status,
    })
    .from(organizationModelCredentials)
    .where(
      and(
        eq(organizationModelCredentials.id, input.credentialId),
        eq(organizationModelCredentials.organizationId, input.organizationId),
        ...(input.provider
          ? [eq(organizationModelCredentials.provider, input.provider)]
          : []),
        eq(organizationModelCredentials.status, "active"),
      ),
    )
    .limit(1);
  const credential = rows[0];
  if (!credential || credential.credentialKeyVersion !== 1) return null;
  if (credential.authType === "chatgpt_subscription") {
    if (credential.provider !== "openai") return null;
    const stored = decryptCredentials<{ authJson: string }>(
      credential.encryptedCredentials,
    );
    parseSubscriptionAuth(stored.authJson);
    return {
      apiKey: "subscription-context-only",
      provider: "openai",
      subscription: {
        credentialId: input.credentialId,
        authJson: stored.authJson,
      },
    };
  }

  const decrypted = decryptCredentials<StoredModelCredential>(
    credential.encryptedCredentials,
  );
  if (!decrypted.apiKey) return null;
  return { apiKey: decrypted.apiKey, provider: credential.provider };
}

// An automation uses the organization's own model access whenever it has some
// for the provider: a ChatGPT subscription for Codex, otherwise the newest
// active API key. Without either, Responder funds inference.
export function chooseOrganizationModelCredential(
  credentials: { id: string; authType: "api_key" | "chatgpt_subscription"; createdAt: Date }[],
  harness: string,
): string | null {
  const newest = [...credentials].sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
  const subscription = harness === "codex"
    ? newest.find((item) => item.authType === "chatgpt_subscription")
    : undefined;
  return (subscription ?? newest.find((item) => item.authType === "api_key"))?.id ?? null;
}

export async function selectOrganizationModelCredential(input: {
