// Another operation holds the refresh token, or the subscription is no longer active.
export class SubscriptionCredentialUnavailableError extends Error {
  constructor() {
    super("This ChatGPT subscription is refreshing or needs reconnecting. Try again shortly.");
    this.name = "SubscriptionCredentialUnavailableError";
  }
}

export async function acquireSubscriptionCredential(input: {
  credentialId: string;
  organizationId: string;
  leaseId: string;
  expiresAt: Date;
}): Promise<string> {
  // Roll back the claim if decryption or validation fails, before any sandbox starts.
  return getDatabase().transaction(async (tx) => {
    const rows = await tx
      .update(organizationModelCredentials)
      .set({
        subscriptionLeaseId: input.leaseId,
        subscriptionLeaseExpiresAt: input.expiresAt,
      })
      .where(
        and(
          eq(organizationModelCredentials.id, input.credentialId),
          eq(organizationModelCredentials.organizationId, input.organizationId),
          eq(organizationModelCredentials.authType, "chatgpt_subscription"),
          eq(organizationModelCredentials.status, "active"),
          // Time alone cannot prove the old sandbox stopped. Fail closed until its owner releases.
          isNull(organizationModelCredentials.subscriptionLeaseId),
        ),
      )
      .returning({
        encryptedCredentials: organizationModelCredentials.encryptedCredentials,
      });
    if (!rows[0]) throw new SubscriptionCredentialUnavailableError();
    const { authJson } = decryptCredentials<{ authJson: string }>(
      rows[0].encryptedCredentials,
    );
    parseSubscriptionAuth(authJson);
    return authJson;
  });
}

export async function persistSubscriptionCredential(input: {
  credentialId: string;
  organizationId: string;
  leaseId: string;
  authJson: string;
  previousAccountId: string;
}): Promise<void> {
  if (
    parseSubscriptionAuth(input.authJson).tokens.account_id !==
    input.previousAccountId
  )
    throw new Error("Subscription account changed during the run");
  const rows = await getDatabase()
    .update(organizationModelCredentials)
    .set({
      encryptedCredentials: encryptCredentials({ authJson: input.authJson }),
      updatedAt: new Date(),
    })
    .where(
      and(
        eq(organizationModelCredentials.id, input.credentialId),
        eq(organizationModelCredentials.organizationId, input.organizationId),
        eq(organizationModelCredentials.authType, "chatgpt_subscription"),
        eq(organizationModelCredentials.subscriptionLeaseId, input.leaseId),
      ),
    )
    .returning({ id: organizationModelCredentials.id });
  if (!rows.length) throw new Error("Subscription credential lease was lost");
}

export async function releaseSubscriptionCredential(input: {
  credentialId: string;
  organizationId: string;
  leaseId: string;
}): Promise<void> {
  await getDatabase()
    .update(organizationModelCredentials)
    .set({ subscriptionLeaseId: null, subscriptionLeaseExpiresAt: null })
    .where(
      and(
        eq(organizationModelCredentials.id, input.credentialId),
        eq(organizationModelCredentials.organizationId, input.organizationId),
        eq(organizationModelCredentials.subscriptionLeaseId, input.leaseId),
      ),
    );
}

const oauthReturnParameters = [
  "error",
  "error_description",
  "signed_up",
  "signup_intent",
];

function cleanOAuthReturnUrl(currentUrl: string): URL {
  const url = new URL(currentUrl);
  for (const parameter of oauthReturnParameters) {
    url.searchParams.delete(parameter);
  }
  return url;
}

export function socialAuthUrls(
  currentUrl: string,
  explicitSignupIntent?: string,
) {
  const returnUrl = cleanOAuthReturnUrl(currentUrl);
  const newUserUrl = new URL(returnUrl);
  newUserUrl.searchParams.set("signed_up", "1");
  if (explicitSignupIntent) {
    newUserUrl.searchParams.set("signup_intent", explicitSignupIntent);
  }

  return {
    callbackURL: returnUrl.toString(),
    errorCallbackURL: returnUrl.toString(),
    newUserCallbackURL: newUserUrl.toString(),
  };
}

export function socialAuthErrorMessage(search: string): string | null {
  const error = new URLSearchParams(search).get("error");
  if (!error) return null;

  if (error === "email_not_found") {
    return "GitHub did not provide an email address. Try again after email access is enabled, or continue with Google or email.";
  }

  return "Social sign in failed. Please try again.";
}

import type { AutomationModelProvider } from "./config.js";
import type { AutomationModelUsage } from "./model-usage.js";

export const aiGatewayBaseUrl = "https://ai-gateway.vercel.sh/v1";

const pricingCacheLifetimeMs = 60 * 60_000;
const pricingRequestTimeoutMs = 10_000;

interface PriceTier {
  cost: string;
  max?: number;
  min: number;
}

export interface GatewayModelPricing {
  input?: string;
  input_cache_read?: string;
  input_cache_read_tiers?: PriceTier[];
  input_cache_write?: string;
  input_cache_write_tiers?: PriceTier[];
  input_tiers?: PriceTier[];
  output?: string;
  output_tiers?: PriceTier[];
}

type PricingFetch = (
  input: string | URL | Request,
  init?: RequestInit,
) => Promise<Response>;

interface GatewayCatalog {
  models: Array<AIGatewayModel & { released?: number }>;
  pricing: Map<string, GatewayModelPricing>;
}

let catalogCache: { catalog: GatewayCatalog; expiresAt: number } | undefined;
let catalogRequest: Promise<GatewayCatalog> | undefined;

export function resetAIGatewayPricingCache(): void {
  catalogCache = undefined;
  catalogRequest = undefined;
}

async function fetchCatalog(fetchCatalogImpl: PricingFetch): Promise<GatewayCatalog> {
  const response = await fetchCatalogImpl(`${aiGatewayBaseUrl}/models`, {
    signal: AbortSignal.timeout(pricingRequestTimeoutMs),
  });
  if (!response.ok) {
    throw new Error(`AI Gateway model catalog returned ${response.status}`);
  }
  const body = (await response.json()) as {
    data?: Array<{ id?: unknown; name?: unknown; pricing?: unknown; released?: unknown; type?: unknown }>;
  };
  const catalog: GatewayCatalog = { models: [], pricing: new Map() };
  for (const model of body.data ?? []) {
    if (typeof model.id !== "string") continue;
    if (model.pricing && typeof model.pricing === "object") {
      catalog.pricing.set(model.id, model.pricing as GatewayModelPricing);
    }
    if (model.type === undefined || model.type === "language") {
      catalog.models.push({
        id: model.id,
        name: typeof model.name === "string" ? model.name : model.id,
        ...(typeof model.released === "number" ? { released: model.released } : {}),
      });
    }
  }
  return catalog;
}

async function loadCatalog(
  dependencies: { fetch?: PricingFetch; now?: () => number },
): Promise<GatewayCatalog> {
  const now = dependencies.now?.() ?? Date.now();
  if (!catalogCache || catalogCache.expiresAt <= now) {
    catalogRequest ??= fetchCatalog(dependencies.fetch ?? fetch).finally(() => {
      catalogRequest = undefined;
    });
    catalogCache = {
      catalog: await catalogRequest,
      expiresAt: now + pricingCacheLifetimeMs,
    };
  }
  return catalogCache.catalog;
}

export async function getAIGatewayModelPricing(
  gatewayModelId: string,
  dependencies: { fetch?: PricingFetch; now?: () => number } = {},
): Promise<GatewayModelPricing | null> {
  return (await loadCatalog(dependencies)).pricing.get(gatewayModelId) ?? null;
}


const aiGatewayCreators: Record<AutomationModelProvider, string | null> = {
  anthropic: "anthropic",
  deepseek: "deepseek",
  google: "google",
  mistral: "mistral",
  openai: "openai",
  xai: "spacexai",
};

// Maps an automation model to an AI Gateway slug. Native Anthropic IDs use
// dashes and may carry a snapshot date; gateway slugs use dotted versions.
export function aiGatewayModelId(
  provider: AutomationModelProvider,
  model: string,
): string {
  if (model.includes("/")) return model;
  if (provider !== "anthropic") {
    return `${aiGatewayCreators[provider] ?? provider}/${model}`;
  }
  // `claude-sonnet-4-5` and legacy `claude-3-5-sonnet` both use a dotted version.
  const undated = model.replace(/-\d{8}$/u, "");
  return `anthropic/${undated.replace(/-(\d+)-(\d+)(?=-|$)/u, "-$1.$2")}`;
}

export interface AIGatewayModel {
  id: string;
  name: string;
}

// Priced language models the gateway serves for one provider, without the
// creator prefix, for the automation model picker. Unpriced models are left
// out because included usage cannot meter them.
export async function listAIGatewayModels(
  provider: AutomationModelProvider,
  dependencies: { fetch?: PricingFetch; now?: () => number } = {},
): Promise<AIGatewayModel[]> {
  const creator = aiGatewayCreators[provider];
  if (!creator) return [];
  const catalog = await loadCatalog(dependencies);
  const zeroUsage = { cacheWriteTokens: 0, cachedInputTokens: 0, inputTokens: 0, outputTokens: 0 };
  return catalog.models
    .filter((model) => {
      const pricing = catalog.pricing.get(model.id);
      return model.id.startsWith(`${creator}/`) &&
        pricing !== undefined &&
        automationModelCostMicros(pricing, zeroUsage) !== null;
    })
    // Newest first; models without a release date go last, by name.
    .sort((a, b) => (b.released ?? 0) - (a.released ?? 0) || a.name.localeCompare(b.name))
    .map((model) => ({ id: model.id.slice(creator.length + 1), name: model.name }));
}

function tierPrice(
  base: string | undefined,
  tiers: PriceTier[] | undefined,
  promptTokens: number,
): number | null {
  const tier = tiers?.find((candidate) =>
    promptTokens >= candidate.min &&
    (candidate.max === undefined || promptTokens < candidate.max)
  );
  const value = Number(tier?.cost ?? base);
  return Number.isFinite(value) && value >= 0 ? value : null;
}

// Returns the request cost in millionths of a US dollar, rounded up.
export function automationModelCostMicros(
  pricing: GatewayModelPricing,
  usage: AutomationModelUsage,
): number | null {
  const promptTokens =
    usage.inputTokens + usage.cachedInputTokens + usage.cacheWriteTokens;
  const input = tierPrice(pricing.input, pricing.input_tiers, promptTokens);
  const output = tierPrice(pricing.output, pricing.output_tiers, promptTokens);
  if (input === null || output === null) return null;
  const cacheRead = tierPrice(
    pricing.input_cache_read,
    pricing.input_cache_read_tiers,
    promptTokens,
  ) ?? input;
  const cacheWrite = tierPrice(
    pricing.input_cache_write,
    pricing.input_cache_write_tiers,
    promptTokens,
  ) ?? input;
  const dollars =
    usage.inputTokens * input +
    usage.cachedInputTokens * cacheRead +
    usage.cacheWriteTokens * cacheWrite +
    usage.outputTokens * output;
  return Math.ceil(dollars * 1_000_000 - 1e-6);
}

